class Solution {
public:
    int uniqueMorseRepresentations(vector<string>& words) {
        vector<string> morse = {".-", "-...", "-.-.", "-..", ".", "..-.", "--.", "....", "..", ".---", "-.-", ".-..", "--",
                                "-.", "---", ".--.", "--.-", ".-.", "...", "-", "..-", "...-", ".--", "-..-", "-.--", "--.."};
        set<string> codes;
        for (int k = 0; k < (int)words.size(); k++) {
            string code;
            for (char c : words[k]) code += morse[c - 'a'];
            codes.insert(code);
        }
        return codes.size();
    }
};
